local Bowyer = {}
local PRODUCTS = {
    self_bow = { name = "Samostrel lok", woodCost = 2, gutCost = 1, time = 2, cost = 30, attack = 6, durability = 18, description = "Preprost lok iz enega kosa lesa." },
    elm_long_bow = { name = "Brestov dolgi lok", woodCost = 3, gutCost = 1, time = 4, cost = 90, attack = 12, durability = 28, prestige = 2, description = "Dolgi lok iz bresta za angleške lokostrelce." },
    yew_recurve_bow = { name = "Tisov povratni lok", woodCost = 3, gutCost = 2, hornCost = 1, time = 6, cost = 220, attack = 18, durability = 35, prestige = 5, happiness = 1, description = "Povratni lok s tiso in rogovi ojačitvami." },
    composite_bow = { name = "Kompozitni lok", woodCost = 3, hornCost = 2, sinewCost = 1, gutCost = 2, time = 9, cost = 480, attack = 24, durability = 45, prestige = 9, happiness = 2, description = "Kompozitni lok z lesom, rogom in kitjo." },
    silver_decorated_bow = { name = "Srebrno okrašen lok", woodCost = 3, silverCost = 1, hornCost = 1, gutCost = 2, time = 11, cost = 950, attack = 30, durability = 55, prestige = 16, happiness = 3, description = "Lok s srebrnim okrasjem za plemiče." },
    royal_ceremonial_bow = { name = "Kraljevski slovesni lok", woodCost = 4, goldCost = 2, silverCost = 1, hornCost = 2, pearlCost = 1, gutCost = 3, time = 15, cost = 2200, attack = 42, durability = 75, prestige = 50, happiness = 10, description = "Veliki kraljevski slovesni lok z zlatim in bisernim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Lokarska delavnica", cost = { gold = 280, wood = 150 }, upkeep = 7, qualityBonus = 5 },
    tillering_room = { name = "Ukrivljalnica", cost = { gold = 850, wood = 250, stone = 200, horn = 8 }, upkeep = 20, qualityBonus = 18 },
    composite_room = { name = "Kompozitna soba", cost = { gold = 1900, wood = 300, stone = 400, silver = 25, sinew = 8 }, upkeep = 45, qualityBonus = 30 },
    royal_bow_atelier = { name = "Kraljevski atelje lokov", cost = { gold = 7500, wood = 600, stone = 800, gold = 50, silver = 30 }, upkeep = 140, qualityBonus = 55, prestigeBonus = 33 },
}
Bowyer.woodStock = 18; Bowyer.gutStock = 14; Bowyer.hornStock = 10; Bowyer.sinewStock = 8; Bowyer.silverStock = 6; Bowyer.goldStock = 6; Bowyer.pearlStock = 4
Bowyer.productStock = {}; Bowyer.buildings = {}; Bowyer.maker = nil; Bowyer.activeMaking = {}; Bowyer.totalProducts = 0; Bowyer.dayTimer = 0
function Bowyer.init() Bowyer.woodStock=18; Bowyer.gutStock=14; Bowyer.hornStock=10; Bowyer.sinewStock=8; Bowyer.silverStock=6; Bowyer.goldStock=6; Bowyer.pearlStock=4; Bowyer.productStock={}; Bowyer.buildings={}; Bowyer.maker=nil; Bowyer.activeMaking={}; Bowyer.totalProducts=0; Bowyer.dayTimer=0; print("[Bowyer] Royal Bowyer System initialized (6 products, 4 buildings)") end
function Bowyer.hireMaker(n,s) s=s or math.random(50,90); local c=490+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Bowyer.maker={name=n or ("Lokar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lokar najet: %s (spretnost: %d)",Bowyer.maker.name,s),"success") end; return true end
function Bowyer.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Bowyer.build(id) local ok,e=Bowyer.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Bowyer.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Bowyer.getQualityBonus() local b=0; for _,bd in ipairs(Bowyer.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Bowyer.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and Bowyer.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.gutCost and Bowyer.gutStock<(d.gutCost or 0) then return false,"Premalo črevesja" end; if d.hornCost and Bowyer.hornStock<(d.hornCost or 0) then return false,"Premalo rogovja" end; if d.sinewCost and Bowyer.sinewStock<(d.sinewCost or 0) then return false,"Premalo kiti" end; if d.silverCost and Bowyer.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and Bowyer.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.pearlCost and Bowyer.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #Bowyer.buildings==0 then return false,"Potrebna delavnica" end; if not Bowyer.maker then return false,"Potreben lokar" end; return true end
function Bowyer.make(pt,qty) qty=qty or 1; local ok,e=Bowyer.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then Bowyer.woodStock=Bowyer.woodStock-d.woodCost*qty end; if d.gutCost then Bowyer.gutStock=Bowyer.gutStock-d.gutCost*qty end; if d.hornCost then Bowyer.hornStock=Bowyer.hornStock-d.hornCost*qty end; if d.sinewCost then Bowyer.sinewStock=Bowyer.sinewStock-d.sinewCost*qty end; if d.silverCost then Bowyer.silverStock=Bowyer.silverStock-d.silverCost*qty end; if d.goldCost then Bowyer.goldStock=Bowyer.goldStock-d.goldCost*qty end; if d.pearlCost then Bowyer.pearlStock=Bowyer.pearlStock-d.pearlCost*qty end; local t=d.time; if Bowyer.maker then t=math.max(1,t-math.floor(Bowyer.maker.skill/12)) end; table.insert(Bowyer.activeMaking,{id="bow_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function Bowyer.completeMaking(m) local q=1.0+(Bowyer.getQualityBonus()/100); if Bowyer.maker then q=q+(Bowyer.maker.skill/180) end; q=math.min(2.0,q); Bowyer.productStock[m.productType]=(Bowyer.productStock[m.productType] or 0)+m.quantity; Bowyer.totalProducts=Bowyer.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if Bowyer.maker then Bowyer.maker.itemsMade=Bowyer.maker.itemsMade+m.quantity; if math.random()<0.20 then Bowyer.maker.skill=math.min(100,Bowyer.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lok izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bow.completed",{productName=m.productName,attack=m.attack,durability=m.durability}) end end
function Bowyer.update(dt) if not _G.state then return end; Bowyer.dayTimer=Bowyer.dayTimer+dt; if Bowyer.dayTimer>=30 then Bowyer.dayTimer=0; for i=#Bowyer.activeMaking,1,-1 do local m=Bowyer.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Bowyer.completeMaking(m); table.remove(Bowyer.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Bowyer.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Bowyer.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Bowyer.getStats() return {woodStock=Bowyer.woodStock,gutStock=Bowyer.gutStock,hornStock=Bowyer.hornStock,sinewStock=Bowyer.sinewStock,silverStock=Bowyer.silverStock,goldStock=Bowyer.goldStock,pearlStock=Bowyer.pearlStock,productStock=Bowyer.productStock,numBuildings=#Bowyer.buildings,hasMaker=Bowyer.maker~=nil,makerName=Bowyer.maker and Bowyer.maker.name or "—",makerSkill=Bowyer.maker and Bowyer.maker.skill or 0,activeMaking=#Bowyer.activeMaking,totalProducts=Bowyer.totalProducts} end
return Bowyer
